LEVEL = 1
CFG = {1: 3, 2: 5, 3: 7}
N = CFG[LEVEL]
LIB = {"timeout:db": "retry", "timeout:api": "retry", "auth:api": "abort", "oom:worker": "escalate"}
failures = [("timeout", "db"), ("auth", "api"), ("timeout", "api"), ("oom", "worker"), ("timeout", "db"), ("disk", "worker"), ("timeout", "db")][:N]
decisions = []
for etype, loc in failures:
    fp = etype + ":" + loc
    decisions.append((fp, LIB.get(fp, "escalate")))
for fp, d in decisions:
    print(fp, "->", d)
print("retryable:", sum(1 for _, d in decisions if d == "retry"))

