LEVEL = 1
CFG = {1: 2, 2: 3, 3: 4}
EXECUTORS = CFG[LEVEL]
escrow = {"payload": {"op": "index", "doc": 42}, "attempts": 0}
result = None
for ex in range(EXECUTORS):
    escrow["attempts"] += 1
    try:
        if ex == 0:
            raise RuntimeError("executor crashed")
        result = "done by executor %d with %s" % (ex, escrow["payload"])
        break
    except RuntimeError:
        continue  # next executor picks up the SAME escrowed payload
print("attempts:", escrow["attempts"], "|", result)

